import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;class PublicExamplesTest{static String capture(Runnable action){PrintStream previous=System.out;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);action.run();}finally{System.setOut(previous);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void dynamicVoiceAndOwnActions(){Object a=TaskBinding.animal(0,"Luna"),d=TaskBinding.animal(1,"Luna"),p=TaskBinding.animal(2,"Luna");String av=TaskBinding.voice(a),dv=TaskBinding.voice(d),pv=TaskBinding.voice(p);for(String s:new String[]{av,dv,pv})assertTrue(s.contains("Luna"));assertNotEquals(av,dv);assertNotEquals(av,pv);assertNotEquals(dv,pv);for(String s:TaskBinding.actions(p))assertFalse(s.isBlank());}}
